UPDATE dish
stall_id = #{stallId}, category_id = #{categoryId}, name = #{name}, description = #{description}, price = #{price}, image = #{image}, daily_stock = #{dailyStock}, status = #{status},
WHERE id = #{id}

UPDATE dish
SET daily_stock = daily_stock - #{quantity}
WHERE id = #{id}
  AND daily_stock >= #{quantity}

UPDATE dish
SET sale_count = sale_count + #{quantity}
WHERE id = #{id}
